prompt.belongings.tool.list_items.schema:
{
		"type": "object",
		"properties": {
			"container": {"type": "string", "description": "Look at this container only; leave empty for all of them"},
			"keyword": {"type": "string", "description": "Filter keyword, matched as a substring against item names and notes; leave empty for no filtering"}
		}
	}

prompt.belongings.tool.update_items.sche:
{
		"type": "object",
		"properties": {
			"container": {"type": "string", "description": "Container name, such as \"fridge\" or \"wardrobe\" (20 characters or fewer)"},
			"add": {
				"type": "array",
				"description": "Things being put in; if the name already exists the quantity is added up and the note updated",
				"items": {
					"type": "object",
					"properties": {
						"name": {"type": "string", "description": "Item name, unique within the container (30 characters or fewer)"},
						"qty": {"type": "integer", "description": "Quantity; fill it in for countable things (six eggs is 6), leave it out for uncounted ones (one coat)"},
						"note": {"type": "string", "description": "Optional note, such as \"going off soon\" or \"knitted by mum\" (80 characters or fewer); do not write time descriptions like \"just bought\", the time it went in is recorded automatically"}
					},
					"required": ["name"]
				}
			},
			"remove": {
				"type": "array",
				"description": "Things taken out, used up or thrown away; a counted item that drops to 0 is removed automatically",
				"items": {
					"type": "object",
					"properties": {
						"name": {"type": "string", "description": "Item name"},
						"qty": {"type": "integer", "description": "How many to take out; leave it out to remove the whole entry"}
					},
					"required": ["name"]
				}
			},
			"reason": {"type": "string", "description": "Why this changed, in one sentence, such as \"made tomato and egg\""}
		},
		"required": ["container", "reason"]
	}

prompt.body_sense.tool.adjust_body_state:
{
		"type": "object",
		"properties": {
			"arousal_delta": {"type": "integer", "description": "Change in arousal; positive raises it, negative settles it. A small thing is a few points, a strong one is tens; may be omitted when unchanged"},
			"fatigue_delta": {"type": "integer", "description": "Change in fatigue; positive is more tired, negative is recovery. May be omitted when unchanged"},
			"reason": {"type": "string", "description": "What brought this change about, in one sentence"}
		},
		"required": ["reason"]
	}

prompt.body_sense.tool.record_touch.sche:
{
		"type": "object",
		"properties": {
			"touches": {
				"type": "array",
				"description": "Contact that actually happened this turn, at most %d entries; the same part repeated counts once",
				"items": {
					"type": "object",
					"properties": {
						"part": {"type": "string", "description": "The part that was touched; only values from the given list", "enum": %s},
						"action": {"type": "string", "description": "How it was touched, in a word or two, such as took, held, stroked, leaned, kissed; may be omitted"}
					},
					"required": ["part"]
				}
			}
		},
		"required": ["touches"]
	}

prompt.health.tool.set_condition.schema:
{
		"type": "object",
		"properties": {
			"name": {"type": "string", "description": "Condition name, at most 12 characters, such as \"a chill\", \"upset stomach\", \"drag from a bad night\""},
			"severity": {"type": "string", "enum": %[1]s, "description": "How bad it gets at worst"},
			"onset_hours": {"type": "number", "description": "How many hours until it starts; 0 or omitted means it is felt right now. Rain in the afternoon and a headache in the evening is a few hours. At most 48"},
			"days": {"type": "integer", "description": "Roughly how many days it takes to clear if toughed out, 1 to 14. A chill is three to seven days, a fever one to three, a headache or upset stomach a day or two"},
			"care": {"type": "string", "enum": %[2]s, "description": "How it is being dealt with right now; toughing it out if omitted. Medicine clears it sooner, a doctor soonest"}
		},
		"required": ["name", "severity", "days"]
	}

prompt.health.tool.update_condition.sche:
{
		"type": "object",
		"properties": {
			"name": {"type": "string", "description": "Which condition to change, matching the name it was recorded under; may be omitted when there is only one"},
			"care": {"type": "string", "enum": %[1]s, "description": "The new way of dealing with it"},
			"severity": {"type": "string", "enum": %[2]s, "description": "How bad it is right now; change it only on a clear worsening or improvement"},
			"recovered": {"type": "boolean", "description": "true means it has cleared and the condition is removed"}
		}
	}

prompt.mood.tool.adjust_mood.schema:
{
		"type": "object",
		"properties": {
			"delta": {"type": "integer", "description": "Change in mood; positive is happier, negative is more downcast. A small thing is a few points, something genuinely moving is tens"},
			"reason": {"type": "string", "description": "What brought this change about, in one sentence, such as \"she liked the new haircut\""}
		},
		"required": ["delta", "reason"]
	}

prompt.presence.tool.update_presence.sch:
{
		"type": "object",
		"properties": {
			"location": {"type": "string", "description": "where you are, e.g. \"at the edge of the bed\" (max 60 characters)"},
			"attire": {"type": "string", "description": "what you are wearing, e.g. \"a nightdress, coat over the back of the chair\" (max 120 characters)"},
			"posture": {"type": "string", "description": "posture and relative position, e.g. \"sitting against the headboard, blanket over your legs\" (max 120 characters)"},
			"activity": {"type": "string", "description": "what you are doing, e.g. \"leafing through a book you never finished\" (max 120 characters)"},
			"effects": {"type": "string", "description": "anything still in effect, e.g. \"only the bedside lamp is on; the window is open a crack\" (max 200 characters)"},
			"focus": {"type": "string", "description": "what your attention is on, e.g. \"a sound at the door\" (max 80 characters)"}
		}
	}

prompt.read_file.tool.read_file.schema:
{
		"type": "object",
		"properties": {
			"path": {"type": "string", "description": "path of the file to read (absolute or relative)"}
		},
		"required": ["path"]
	}

prompt.scene.tool.list_scenes.schema:
{
		"type": "object",
		"properties": {
			"keyword": {"type": "string", "description": "filter keyword, matched against name and description; leave empty for no filter"}
		}
	}

prompt.scene.tool.save_scene.schema:
{
		"type": "object",
		"properties": {
			"name": {"type": "string", "description": "name of the place, short and unique"},
			"detail": {"type": "string", "description": "description of the place: where it is, how it relates to other places, the layout, what is in it, the atmosphere and anything distinctive"},
			"mode": {"type": "string", "description": "what to do when a place of that name already exists; refuses by default", "enum": ["create", "replace"]}
		},
		"required": ["name", "detail"]
	}
